param([string]$Directory,[string]$Native,[string]$Harness,[int]$OwnerPid,[string]$Nonce)
$ErrorActionPreference='Stop';Add-Type -AssemblyName System.Web.Extensions
function Part([string]$Text,[string]$Start,[string]$End){$a=$Text.IndexOf($Start,[StringComparison]::Ordinal);if($a -lt 0){throw 'Production start missing'};$b=$Text.IndexOf($End,$a+$Start.Length,[StringComparison]::Ordinal);if($b -le $a){throw 'Production end missing'};return $Text.Substring($a,$b-$a)}
$broker=[IO.File]::ReadAllText((Join-Path $Native 'HyperVBroker.cs'));$snapshots=[IO.File]::ReadAllText((Join-Path $Native 'SnapshotOperations.cs'));$backup=[IO.File]::ReadAllText((Join-Path $Native 'BackupRead.cs'))
$parts=@((Part $broker '    private static void ValidateKeys(' '    private static void ValidateLedgerFile('),(Part $broker '    private static Dictionary<string,object> Owned(' '    private static string Invoke('),(Part $broker '    private static byte[] ReadRequest(Stream pipe)' '    private static void Shutdown()'),(Part $broker '    private static void RequestBounds(' '    private static bool OwnerExited'),(Part $broker '    private static bool OwnerExited' '    private static DirectorySecurity PrivateAcl()'),(Part $broker '    private static bool QuiesceWriteAction(' '    private static void BeginQuiescing('),(Part $snapshots '    private static string SnapshotCipher(' '    private static object SnapshotDescriptor('))
$start=$backup.IndexOf('    private sealed class SnapshotExportState',[StringComparison]::Ordinal);if($start -lt 0){throw 'Production historical lane missing'};$historical='public static partial class MuHyperVBroker {'+[Environment]::NewLine+$backup.Substring($start)
$source=[IO.File]::ReadAllText($Harness)+[Environment]::NewLine+[IO.File]::ReadAllText((Join-Path $Native 'OfflineSnapshots.cs'))+[Environment]::NewLine+[IO.File]::ReadAllText((Join-Path $Native 'SnapshotStaging.cs'))+[Environment]::NewLine+$historical+[Environment]::NewLine+'public static partial class MuHyperVBroker {'+[Environment]::NewLine+($parts -join [Environment]::NewLine)+[Environment]::NewLine+'}'
Add-Type -TypeDefinition $source -ReferencedAssemblies @('System.dll','System.Core.dll','System.Web.Extensions.dll')
[MuHyperVBroker]::Run($Directory,$OwnerPid,$Nonce)
